package com.dtm.platform.config;import org.springframework.context.annotation.*;import io.swagger.v3.oas.models.*;import io.swagger.v3.oas.models.info.*;import io.swagger.v3.oas.models.security.*;
@Configuration public class OpenApiConfig {@Bean OpenAPI openAPI(){return new OpenAPI().info(new Info().title("DTM Engineering Platform API").version("v1").description("Public published content and authenticated ADMIN/EDITOR CMS. Credentials never returned in content responses.")).components(new Components().addSecuritySchemes("bearerAuth",new SecurityScheme().type(SecurityScheme.Type.HTTP).scheme("bearer").bearerFormat("JWT")));}}
